:root { font-family: system-ui, sans-serif; color: #182b40; background: #f5f7fa; }
body { margin: 0; }
main { max-width: 760px; margin: 64px auto; padding: 28px; background: white; border: 1px solid #dce3eb; border-radius: 12px; }
h1 { margin-top: 0; overflow-wrap: anywhere; }
form { display: flex; flex-wrap: wrap; align-items: center; gap: 12px; margin-bottom: 24px; }
label { font-weight: 600; }
input { flex: 1; min-width: 140px; padding: 10px; border: 1px solid #8796a8; border-radius: 6px; font: inherit; }
button { padding: 10px 16px; border: 1px solid #2456a0; border-radius: 6px; background: #2456a0; color: white; font: inherit; cursor: pointer; }
button:hover { background: #1a407a; }
button:disabled { opacity: .6; cursor: wait; }
:focus-visible { outline: 3px solid #d58a00; outline-offset: 3px; }
.project-row { display: flex; align-items: center; justify-content: space-between; gap: 16px; border-top: 1px solid #dce3eb; padding: 16px 0; }
.project-row span { overflow-wrap: anywhere; min-width: 0; }
.project-row button { flex-shrink: 0; }
[role="alert"] { color: #a32020; }
@media (max-width: 600px) { main { margin: 20px 12px; padding: 20px; } }

